INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'ammortamento-alla-francese-guida-mutuo-rata-costante',
    'Ammortamento alla francese: come si calcola davvero la rata del mutuo',
    'Perché la rata del mutuo resta identica ogni mese ma la parte di interessi e capitale cambia continuamente, spiegato con un esempio numerico reale.',
    'Come funziona l''ammortamento alla francese dei mutui italiani: rata costante, quota capitale e quota interessi spiegate con un esempio numerico.',
    'mutui',
    '🏠',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se hai un mutuo in Italia, quasi certamente lo stai rimborsando con il metodo di ammortamento alla francese: è lo standard usato dalla grande maggioranza delle banche italiane, ed è il motivo per cui la tua rata mensile resta identica dal primo all''ultimo mese, anche se la composizione interna cambia continuamente.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il principio: rata costante, proporzione variabile</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ogni rata è formata da due parti: la <strong>quota capitale</strong> (quanto stai davvero restituendo del debito) e la <strong>quota interessi</strong> (il costo del prestito per quel mese). Nell''ammortamento alla francese la somma delle due resta sempre uguale, ma il loro peso reciproco no.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">All''inizio del mutuo il debito residuo è alto, quindi gli interessi maturati su quella cifra sono alti: la maggior parte della rata va a pagare interessi, e solo una piccola quota riduce davvero il capitale. Con il passare degli anni il debito residuo scende, quindi scendono anche gli interessi maturati mese per mese, e la quota capitale cresce di conseguenza — pur restando la rata sempre identica.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Un esempio numerico</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un mutuo di 150.000&euro; a 25 anni con tasso fisso al 3,5% ha una rata mensile di circa 751&euro;. Nella <strong>prima rata</strong>, circa 438&euro; sono interessi e solo 313&euro; riducono il capitale. Nell''<strong>ultima rata</strong>, la proporzione si ribalta quasi completamente: pochi euro di interessi, quasi tutto capitale. Ecco perché negli anni iniziali il debito residuo scende così lentamente rispetto a quanto ci si aspetterebbe guardando solo l''importo pagato.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché conta saperlo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Capire questa meccanica cambia il modo in cui guardi al tuo mutuo. Un pagamento extra fatto nei primi anni pesa molto di più sugli interessi complessivi che pagherai, proprio perché in quel momento il debito residuo (e quindi la base su cui maturano gli interessi futuri) è ancora alto — è uno dei motivi per cui vale la pena valutare un''estinzione parziale anticipata quando possibile (ne parliamo in dettaglio in <a href="/news/estinzione-anticipata-mutuo-quando-conviene" class="text-accent hover:underline font-medium">questo articolo</a>).</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Vale anche per i mutui cointestati: se possiedi il 50% di un immobile, la tua quota reale di capitale e interessi va calcolata sulla tua percentuale di proprietà, non sulla rata intera — un dettaglio che molti strumenti di calcolo generici ignorano.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Vedere il tuo piano di ammortamento reale</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Su <a href="/mutui.php" class="text-accent hover:underline font-medium">Reflexi</a> il piano di ammortamento del tuo mutuo è calcolato mese per mese sul tuo tasso e la tua quota di proprietà reale, con la simulazione di quanto risparmieresti estinguendolo in anticipo, oggi o a una data futura.</p>',
    'pubblicato',
    '2026-08-05 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'pac-piano-accumulo-etf-come-funziona',
    'PAC: cos''è un piano di accumulo in ETF e come funziona',
    'Versare una cifra fissa ogni mese invece di investire tutto insieme: come funziona il dollar-cost averaging e perché è il punto di partenza più comune per chi inizia a investire.',
    'Cos''è un PAC (piano di accumulo capitale) in ETF, come funziona il dollar-cost averaging e quando conviene rispetto a un investimento in un''unica soluzione.',
    'investimenti',
    '📈',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">PAC è l''acronimo di <strong>Piano di Accumulo Capitale</strong>: invece di investire una somma unica in un colpo solo, versi un importo fisso a intervalli regolari (di solito ogni mese) in uno o più strumenti, tipicamente ETF. È probabilmente il modo più diffuso per iniziare a investire per chi parte da uno stipendio, non da un capitale già accumulato.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come funziona in pratica</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Imposti un importo (es. 200&euro;) e una cadenza (es. il 5 di ogni mese). A ogni scadenza, quell''importo compra automaticamente quote dell''ETF scelto al prezzo di quel momento — a volte più alto, a volte più basso. Nel tempo, questo genera un effetto chiamato <strong>dollar-cost averaging</strong> (mediazione del costo): compri più quote quando il prezzo è basso e meno quote quando il prezzo è alto, il che abbassa il prezzo medio di carico rispetto a investire tutto insieme in un momento potenzialmente sbagliato.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché funziona bene per chi investe per la prima volta</h2><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Non serve indovinare il momento giusto</strong> — il timing perfetto sui mercati è quasi impossibile anche per i professionisti; il PAC lo rende irrilevante.</li><li><strong>Costruisce l''abitudine</strong> — versamenti automatici regolari sono più facili da sostenere di una decisione grande e unica.</li><li><strong>Riduce l''impatto emotivo</strong> — investendo un po'' alla volta, un crollo di mercato pesa meno psicologicamente su chi sta iniziando.</li></ul><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Un limite da conoscere</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Se i mercati salgono in modo continuo per un lungo periodo, un investimento in un''unica soluzione fatto all''inizio avrebbe reso di più di un PAC distribuito nel tempo — perché il capitale resta investito più a lungo. Il PAC non è la strategia matematicamente ottimale in ogni scenario: è una strategia che riduce il rischio percepito e rende più facile restare investiti a lungo, il che conta più della teoria quando si parla di comportamento reale delle persone.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Calcolare quanto potresti accumulare</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-piano-investimento.php" class="text-accent hover:underline font-medium">calcolatore piano di investimento periodico</a> puoi simulare quanto accumuleresti versando una cifra fissa ogni mese a un rendimento medio atteso, anno per anno.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/investimenti.php" class="text-accent hover:underline font-medium">Su Reflexi</a>, un PAC si imposta indicando importo e intervallo: quando premi «Genera acquisti dovuti», l''app calcola da sola quante quote comprare al prezzo di chiusura reale di ogni data dovuta, e tiene il costo medio di carico aggiornato automaticamente — utile anche per il calcolo delle imposte quando vendi.</p>',
    'pubblicato',
    '2026-08-08 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'regola-50-30-20-vs-budget-per-categoria',
    'Regola 50/30/20 o budget per categoria: quale metodo scegliere',
    'La regola 50/30/20 è un ottimo punto di partenza, ma ha limiti concreti. Quando conviene passare a un budget per categoria con limiti reali.',
    'Confronto tra la regola di budget 50/30/20 e il budget per categoria: vantaggi, limiti e quale approccio scegliere in base alla tua situazione.',
    'budget',
    '🥧',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Chiunque inizi a occuparsi di budget personale incontra presto la <strong>regola 50/30/20</strong>: 50% del reddito netto per le necessità, 30% per i desideri, 20% per risparmio e investimenti. È semplice, memorizzabile in dieci secondi, e per questo è diventata il punto di partenza più diffuso. Ma non è l''unico approccio, e non sempre è quello giusto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">I limiti della regola 50/30/20</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">La regola funziona come linea guida generale, ma ha due problemi concreti. Il primo: in molte città italiane l''affitto o il mutuo da solo può superare il 40-50% del reddito netto, rendendo il vincolo del 50% per tutte le necessità semplicemente irrealistico senza colpa di chi lo applica. Il secondo: tratta tutte le «necessità» o tutti i «desideri» come un blocco unico, senza dirti dove va davvero il denaro — se il problema è la spesa alimentare o i ristoranti, la regola non lo rivela.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">L''alternativa: budget per categoria</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Un budget per categoria parte dal basso: guardi le tue spese reali degli ultimi mesi, categoria per categoria (spesa, ristoranti, trasporti, abbonamenti...), e imposti un limite specifico per ognuna in base a dove vuoi davvero intervenire — non a una percentuale generica calata dall''alto.</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Più preciso</strong> — un limite di 150&euro; sui ristoranti dice qualcosa di azionabile; il 30% per i «desideri» no.</li><li><strong>Si adatta alla tua situazione reale</strong> — non c''è una percentuale valida per tutti quando affitti, stipendi e città variano così tanto.</li><li><strong>Può avere rollover</strong> — se una categoria non spende tutto il budget in un mese, l''eccedenza si riporta al mese successivo invece di sparire, utile per spese irregolari come manutenzioni o regali.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Quale scegliere</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il 50/30/20 resta un ottimo <strong>punto di partenza</strong> se non hai mai tracciato le tue spese e vuoi un primo orientamento in trenta secondi, senza dover analizzare nulla — puoi provarlo subito con il <a href="/calcolatore-budget-503020.php" class="text-accent hover:underline font-medium">calcolatore gratuito</a>.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Ma se vuoi davvero controllare dove va il tuo denaro e correggere abitudini specifiche, un budget per categoria con limiti reali (e un avviso prima di sforare, non dopo) fa un lavoro che una regola generica non può fare. Non sono alternative esclusive: molte persone usano il 50/30/20 come cornice iniziale, poi passano a <a href="/budget.php" class="text-accent hover:underline font-medium">un budget per categoria</a> quando vogliono più precisione.</p>',
    'pubblicato',
    '2026-08-11 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'interesse-composto-esempi-reali',
    'Interesse composto spiegato con esempi reali: perché iniziare prima conta più di quanto pensi',
    'Perché pochi anni di differenza nell''iniziare a investire possono valere più di anni di versamenti extra. L''interesse composto spiegato con numeri veri.',
    'Come funziona l''interesse composto e perché il tempo conta più dell''importo versato, spiegato con esempi numerici reali su 10, 20 e 30 anni.',
    'investimenti',
    '🧮',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Albert Einstein non ha mai davvero detto che l''interesse composto è «l''ottava meraviglia del mondo» (la citazione è apocrifa), ma l''idea di fondo è comunque corretta: pochi meccanismi finanziari hanno un effetto così grande sul lungo periodo, ed è così controintuitivo che vale la pena vederlo con numeri reali.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La differenza tra interesse semplice e composto</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con l''<strong>interesse semplice</strong>, guadagni sempre sulla stessa cifra iniziale. Con l''<strong>interesse composto</strong>, gli interessi maturati si sommano al capitale e a loro volta generano altri interessi nei periodi successivi — guadagni sui guadagni, non solo sul capitale di partenza.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Un esempio concreto</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">10.000&euro; investiti a un rendimento medio del 7% annuo, reinvestendo sempre i guadagni: dopo 10 anni diventano circa 19.670&euro;. Dopo 20 anni, circa 38.700&euro;. Dopo 30 anni, circa 76.100&euro;. Nota che il capitale non è raddoppiato due volte in modo lineare tra i 10 e i 30 anni: è quasi <strong>quadruplicato</strong> rispetto ai primi 10 anni, perché ogni anno in più compone su una base sempre più grande.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché il tempo conta più dell''importo versato</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Chi inizia a investire 200&euro; al mese a 25 anni e smette a 35 (versando per soli 10 anni, poi lasciando il capitale investito senza più toccarlo) può arrivare a 65 anni con un capitale simile o superiore a chi inizia a 35 anni versando 200&euro; al mese fino a 65 — pur avendo versato una frazione del totale. La differenza è interamente il tempo in più concesso all''effetto composto per lavorare.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Questo non significa che iniziare tardi sia inutile — significa solo che il costo reale di rimandare non è «qualche mese di versamenti persi», ma anni di crescita composta su quei versamenti che non torna indietro.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Fai i tuoi calcoli</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <a href="/calcolatore-interesse-composto.php" class="text-accent hover:underline font-medium">calcolatore di interesse composto</a> puoi inserire capitale iniziale, versamenti periodici, rendimento atteso e orizzonte temporale, e vedere subito la crescita anno per anno. <a href="/investimenti.php" class="text-accent hover:underline font-medium">Su Reflexi</a>, lo stesso principio si applica al tuo portafoglio reale: il grafico storico mostra come il tuo capitale composto sta crescendo davvero, non solo in teoria.</p>',
    'pubblicato',
    '2026-08-14 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'estinzione-anticipata-mutuo-quando-conviene',
    'Estinzione anticipata del mutuo: quando conviene davvero',
    'Estinguere il mutuo in anticipo non è sempre la scelta migliore: il confronto che conta è tra il tasso del tuo mutuo e il rendimento atteso di un''alternativa.',
    'Quando conviene estinguere anticipatamente un mutuo: il confronto tra tasso del mutuo e rendimento alternativo, penali e fattori non finanziari da considerare.',
    'mutui',
    '⏳',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Estinguere in anticipo (in parte o del tutto) un mutuo sembra sempre una buona idea: meno debito, meno interessi futuri, più tranquillità. Ma non è sempre la scelta finanziariamente migliore — dipende da un confronto preciso che spesso non viene fatto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa succede davvero quando estingui in anticipo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con l''ammortamento alla francese, ogni euro di capitale restituito in anticipo elimina tutti gli interessi futuri che sarebbero maturati su quella cifra fino alla scadenza naturale del mutuo. Più è presto nella vita del mutuo, maggiore è il risparmio sugli interessi — perché il debito residuo (e quindi la base di calcolo degli interessi) è ancora alto (lo spieghiamo in dettaglio in <a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">questo articolo</a>).</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Il confronto che conta davvero: tasso del mutuo vs rendimento alternativo</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il risparmio sugli interessi da un''estinzione anticipata equivale, in pratica, a un rendimento <strong>certo e senza rischio</strong> pari al tasso del tuo mutuo. Se il tuo mutuo ha un tasso fisso al 2%, e potresti investire quella stessa somma in uno strumento diversificato con un rendimento atteso storico del 6-7% annuo (seppur non garantito), matematicamente potrebbe convenirti di più investire piuttosto che estinguere. Se invece il tuo mutuo ha un tasso al 4-5%, il confronto si stringe molto, e la certezza del risparmio sugli interessi comincia a pesare di più.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">Non è solo matematica</h3><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Tranquillità psicologica</strong> — un debito in meno ha un valore che non compare in nessuna formula, per molte persone conta davvero.</li><li><strong>Liquidità</strong> — i soldi usati per estinguere non sono più disponibili per emergenze; un investimento resta (quasi sempre) liquidabile.</li><li><strong>Penali</strong> — verifica sempre se il tuo contratto prevede una penale di estinzione anticipata, che riduce il vantaggio del calcolo.</li></ul><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Simula il tuo caso specifico</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700"><a href="/mutui.php" class="text-accent hover:underline font-medium">Su Reflexi</a>, la simulazione di estinzione anticipata calcola esattamente quanto risparmieresti in interessi estinguendo oggi (o a una data futura) rispetto a continuare fino alla scadenza naturale, sul tuo mutuo reale — non su un caso generico. Puoi anche confrontare lo scenario con il <a href="/calcolatore-recupero-perdite.php" class="text-accent hover:underline font-medium">calcolatore di rendimento</a> per farti un''idea di cosa renderebbe la stessa somma se investita invece che usata per estinguere.</p>',
    'pubblicato',
    '2026-08-17 09:00:00'
);

INSERT INTO news_articles
    (slug, title, excerpt, meta_description, category, cover_emoji, body, status, published_at)
VALUES (
    'indipendenza-finanziaria-fire-come-calcolare-il-numero',
    'Indipendenza finanziaria (FIRE): cos''è e come calcolare il tuo numero',
    'Cos''è il movimento FIRE, come si calcola il proprio «numero» con la regola del 4% e perché non è una garanzia ma una stima statistica.',
    'Cos''è l''indipendenza finanziaria (FIRE) e come calcolare il capitale necessario per raggiungerla con la regola del 4%, spiegata con esempi.',
    'pianificazione',
    '🔥',
    '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">FIRE è l''acronimo di <strong>Financial Independence, Retire Early</strong> (indipendenza finanziaria, pensione anticipata): un movimento nato negli Stati Uniti che si è diffuso globalmente, basato su un''idea semplice da enunciare e più impegnativa da realizzare — accumulare un capitale abbastanza grande da vivere di rendita, senza dipendere da uno stipendio.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Cosa significa «indipendenza finanziaria» in pratica</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Non significa necessariamente smettere di lavorare per sempre — significa avere la <strong>possibilità di scegliere</strong>: continuare a lavorare perché lo vuoi, cambiare carriera senza paura economica, ridurre le ore, o davvero ritirarti prima dell''età pensionabile standard. Il capitale accumulato genera reddito passivo sufficiente a coprire le spese, rendendo lo stipendio opzionale invece che necessario.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Come si calcola il proprio «numero»</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Il punto di partenza più comune è la <strong>regola del 4%</strong> (basata sullo studio storico noto come Trinity Study): se ogni anno prelevi il 4% del tuo capitale investito, statisticamente il capitale ha un''alta probabilità di durare almeno 30 anni, considerando la crescita media dei mercati nel tempo. Da questa regola si ricava il «numero FIRE»: le tue spese annuali moltiplicate per 25.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Esempio: se vivi con 30.000&euro; l''anno, il tuo numero FIRE è circa 750.000&euro; investiti. Con spese annuali di 20.000&euro;, scende a 500.000&euro;. Il numero dipende quasi interamente dal tuo tenore di vita, non dal tuo reddito attuale — due persone con lo stesso stipendio possono avere numeri FIRE molto diversi in base a quanto spendono davvero.</p><h3 class="mt-6 mb-2 text-lg font-bold text-gray-900">La regola del 4% non è una garanzia</h3><p class="mb-4 text-[15px] leading-relaxed text-gray-700">È una stima statistica basata su dati storici passati (soprattutto mercato americano del Novecento), non una promessa: sequenze di rendimenti negativi nei primi anni di prelievo (il cosiddetto «sequence risk») possono ridurre la probabilità di successo. Molti nella comunità FIRE usano percentuali più prudenti (3-3,5%) per aumentare il margine di sicurezza.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Perché serve vedere tutto insieme, non solo gli investimenti</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Calcolare il proprio numero FIRE richiede di conoscere davvero le proprie spese medie reali (non una stima approssimativa), il tasso di risparmio effettivo, e come mutuo, investimenti e spese quotidiane interagiscono nel tempo — non tre pezzi scollegati. La sezione <a href="/analisi.php" class="text-accent hover:underline font-medium">Analisi predittiva</a> di Reflexi usa la tua storia finanziaria reale (non ipotesi generiche) per proiettare scenari futuri con simulazione Monte Carlo, un punto di partenza molto più concreto di una stima fatta su un foglio a parte.</p>',
    'pubblicato',
    '2026-08-19 09:00:00'
);

